 register({name:'search_shared_guide',title:'Search shared guide',description:'Search the bilingual guide, show matching entries, and return their titles and sources. Does not send a message.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.query!=='string'||input.query.length>100||Object.keys(input).some(k=>k!=='query'))throw Error('invalidInput');$('guide-search').value=input.query;showTab('guide');renderGuides();const q=input.query.toLowerCase();return {guides:guides.filter(g=>(g.keywords+' '+JSON.stringify(g.en)+' '+JSON.stringify(g.zh)).toLowerCase().includes(q)).map(g=>({id:g.id,title:g[language].title,source:g.url}))};}});
 register({name:'read_community_questions',title:'Read community questions',description:'Read the latest questions available to the signed-in member. Does not post or send anything. Requires a completed profile.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('invalidInput');if(!state.profile)throw Error('signIn');await loadQuestions();return {questions:state.questions.slice(0,20).map(q=>({id:q.id,title:q.title,topic:q.topic}))};}});
